  const BRIGADE_ROOT = '#v169-brigade-container';
  let timer = null;
  let syncing = false;
  let rerun = false;
  let queuedReason = 'brigade';
  const safeCall = (fn, ...args) => {
    try {
      return typeof fn === 'function' ? fn(...args) : undefined;
    } catch (error) {
      console.warn('[iCHEF RH V187] appel non bloquant', error);
      return undefined;
    }
  };
